entries[298930] = { ["name"] = "Blingtron 7000", ["text"] = "2 sec cast\nTools: Blacksmith Hammer , Gyromatic Micro-Adjustor\nReagents:\nPlatinum Ore (5), Storm Silver Ore (10), Amberblaze (3), Laribole (3), Insulated Wiring (25)\nCraft Blingtron 7000.\nVendor:\nStolen Royal Vendorbot\nZone:\nMechagon\nRustbolt Resistance - Exalted\nCost:\n1900\n\nBlingtron 7000\nBinds when picked up\nToy\nUse: Assembles the upgraded Blingtron 7000, a savage, yet generous, robot. While he will give out gifts to players once per day, he will also fight other Blingtron units to the death. (4 Hrs Cooldown)\nRequires Kul Tiran Engineering\n(1)" }
